-- 모든 일반사용자에게 2026년도 포인트 지급
SELECT id,
  CASE rank
    WHEN 'colonel' THEN 800000 WHEN 'lt_colonel' THEN 800000 WHEN 'major' THEN 800000
    WHEN 'captain' THEN 600000 WHEN 'first_lt' THEN 600000 WHEN 'second_lt' THEN 600000
    WHEN 'warrant' THEN 500000 WHEN 'sgt_major' THEN 400000 WHEN 'master_sgt' THEN 400000
    WHEN 'sgt' THEN 400000 WHEN 'civil_servant' THEN 400000
    ELSE 0
  END + (EXTRACT(YEAR FROM CURRENT_DATE) - EXTRACT(YEAR FROM enlist_date))::int * 5000,
  0, 0
FROM users WHERE role = 'user';

SELECT id, 'grant',
  CASE rank
    WHEN 'colonel' THEN 800000 WHEN 'lt_colonel' THEN 800000 WHEN 'major' THEN 800000
    WHEN 'captain' THEN 600000 WHEN 'first_lt' THEN 600000 WHEN 'second_lt' THEN 600000
    WHEN 'warrant' THEN 500000 WHEN 'sgt_major' THEN 400000 WHEN 'master_sgt' THEN 400000
    WHEN 'sgt' THEN 400000 WHEN 'civil_servant' THEN 400000
    ELSE 0
  END + (EXTRACT(YEAR FROM CURRENT_DATE) - EXTRACT(YEAR FROM enlist_date))::int * 5000,
  '2026년도 피복포인트 지급', 'annual', 2026, 'c1000000-0000-0000-0000-000000000001'
FROM users WHERE role = 'user';

